import QtQuick
import QtQuick.Controls

// 005 U8: one editable pose cell of the Poses dialog table. Pure view glue
// (no logic — the commit + validation live in PoseBridge):
//  - the stored value comes from the table model's role (re-reads on
//    dataChanged / table reset — the model is the authoritative display
//    source);
//  - on editingFinished the text commits through PoseBridge::setPoseValue
//    (immediate per-cell SavePose). A rejected commit (non-numeric / NaN /
//    out-of-range) leaves the stored state unchanged: the field reverts to
//    the stored value and the bridge's inline validation message shows.
===
            }

            // ---- The editable table (scrolls when the column is short) --
            ScrollView {
                id: poseScroll
                Layout.fillWidth: true
                Layout.fillHeight: true
                clip: true
                // Hidden only without a dataset + primary model; during an
                // optimizer run it stays visible but disabled (the U6
                // locking — the Run button also closes this dialog).
                visible: poseBridge.rowCount > 0
                         && studyBridge.primaryModelIndex >= 0
                enabled: !optimizerBridge.running

                Column {
                    width: poseScroll.availableWidth
                    spacing: 2

                    Repeater {
                        model: poseBridge.tableModel
                        delegate: RowLayout {
                            Layout.fillWidth: true
                            spacing: 4
                            Label {
                                text: qsTr("F%1").arg(model.frameIndex)
                                width: 44
                                horizontalAlignment: Text.AlignRight
                                color: Theme.fgMuted
                                font.pixelSize: 11
                            }
                            PoseCell {
                                frameRow: model.frameIndex
                                axisIndex: 0
                                storedValue: model.x
                            }
                            PoseCell {
                                frameRow: model.frameIndex
                                axisIndex: 1
                                storedValue: model.y
                            }
                            PoseCell {
                                frameRow: model.frameIndex
                                axisIndex: 2
                                storedValue: model.z
                            }
                            PoseCell {
                                frameRow: model.frameIndex
                                axisIndex: 3
                                storedValue: model.xa
                            }
                            PoseCell {
                                frameRow: model.frameIndex
                                axisIndex: 4
                                storedValue: model.ya
                            }
                            PoseCell {
                                frameRow: model.frameIndex
                                axisIndex: 5
                                storedValue: model.za
                            }
                        }
                    }
                }
            }

            // ---- Inline validation message (review fix) -----------------
            Label {
                Layout.fillWidth: true
                visible: poseBridge.validationMessage.length > 0
                color: Theme.badge
                font.pixelSize: 11
                wrapMode: Text.Wrap
                text: poseBridge.validationMessage
            }
        }
    }

    // ---- Bridge → view glue (U4) ---------------------------------------
    Connections {
        target: studyBridge

